"""
AI 百人導師團隊公開介紹頁。跑法：python app.py（預設 port 5062，獨立Cloudflare通道對外開）
導師點LINE群組連結 → /join 填表傳照片 → 立刻寫入資料庫、馬上出現在 / 首頁（沒有審核關卡）
教練看名單/補種子資料/修正錯誤 → /admin（帳密登入，見 /admin/login）
"""
import os
import re
import secrets
import time
from collections import defaultdict
from io import BytesIO

from flask import Flask, abort, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash
from PIL import Image, ImageOps, UnidentifiedImageError

import db

app = Flask(__name__)
app.secret_key = os.environ.get("MENTOR100_SECRET_KEY", "")
ADMIN_USER = os.environ.get("MENTOR100_ADMIN_USER", "")
ADMIN_PASSWORD_HASH = os.environ.get("MENTOR100_ADMIN_PASSWORD_HASH", "")

UPLOAD_DIR = os.path.join(os.path.dirname(__file__), "static", "uploads")
ALLOWED_EXTS = {"jpg", "jpeg", "png", "webp"}
MAX_PHOTO_EDGE = 1200
app.config["MAX_CONTENT_LENGTH"] = 8 * 1024 * 1024  # 8MB

_rate_limit_log: dict[str, list[float]] = defaultdict(list)
RATE_LIMIT_MAX = 5
RATE_LIMIT_WINDOW = 3600  # 1 小時


def _sanitize_filename(raw: str) -> str:
    """保留中文檔名，只擋掉路徑穿越與危險字元。
    不能直接用werkzeug的secure_filename——它會把中文整段砍掉。"""
    name = os.path.basename(raw).replace("\x00", "")
    name = re.sub(r'[/\\:*?"<>|]', "", name)
    return name.strip() or "file"


def _process_and_save_photo(file_storage) -> str | None:
    """驗證是不是真的圖片、轉正方向、縮圖存檔。回傳存檔後的檔名；失敗回傳 None。
    近百位導師各自上傳，檔名很容易撞名（例如都叫IMG_1234.JPG），
    所以消毒後一律加隨機後綴，不會互相覆蓋。"""
    raw_name = _sanitize_filename(file_storage.filename or "photo.jpg")
    ext = raw_name.rsplit(".", 1)[-1].lower() if "." in raw_name else ""
    if ext not in ALLOWED_EXTS:
        ext = "jpg"

    try:
        data = file_storage.read()
        img = Image.open(BytesIO(data))
        img.verify()
        img = Image.open(BytesIO(data))  # verify() 後要重新開才能再讀
        img = ImageOps.exif_transpose(img)
        if img.mode not in ("RGB", "L"):
            img = img.convert("RGB")
    except (UnidentifiedImageError, OSError):
        return None

    img.thumbnail((MAX_PHOTO_EDGE, MAX_PHOTO_EDGE))

    stem = raw_name.rsplit(".", 1)[0] if "." in raw_name else raw_name
    filename = f"{stem}-{secrets.token_hex(4)}.jpg"
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    img.save(os.path.join(UPLOAD_DIR, filename), "JPEG", quality=85)
    return filename


def _check_rate_limit(ip: str) -> bool:
    """回傳 True 代表可以送出，False 代表這個IP這小時已經送太多次。"""
    now = time.time()
    log = _rate_limit_log[ip]
    log[:] = [t for t in log if now - t < RATE_LIMIT_WINDOW]
    if len(log) >= RATE_LIMIT_MAX:
        return False
    log.append(now)
    return True


def _extract_links(form) -> dict:
    cols = (*db.LINK_COLUMNS, *db.LABEL_COLUMNS)
    return {col: (form.get(col) or "").strip() for col in cols}


@app.route("/")
def index():
    conn = db.get_conn()
    mentors = [{**dict(m), "links": db.mentor_links(m)} for m in db.list_mentors(conn)]
    conn.close()
    return render_template("index.html", mentors=mentors)


@app.route("/join", methods=["GET"])
def join_form():
    return render_template("join.html", error=None, form={})


@app.route("/join", methods=["POST"])
def join_submit():
    # honeypot：一般人看不到這個欄位，機器人才會填
    if (request.form.get("website") or "").strip():
        return redirect(url_for("join_thanks"))

    ip = request.remote_addr or "unknown"
    if not _check_rate_limit(ip):
        return render_template(
            "join.html", error="這個小時送出次數太多了，請稍後再試一次", form=request.form
        ), 429

    name = (request.form.get("name") or "").strip()
    company_title = (request.form.get("company_title") or "").strip()
    role_tag = (request.form.get("role_tag") or "").strip()
    bio = (request.form.get("bio") or "").strip()
    links = _extract_links(request.form)
    photo = request.files.get("photo")

    error = None
    if not name:
        error = "請填寫姓名"
    elif not company_title:
        error = "請填寫公司/職稱"
    elif not bio:
        error = "請填寫簡介"
    elif not photo or not photo.filename:
        error = "請上傳一張照片"

    filename = None
    if not error:
        filename = _process_and_save_photo(photo)
        if not filename:
            error = "這張照片打不開，麻煩改存成 jpg 或 png 格式再上傳一次"

    if error:
        return render_template(
            "join.html", error=error,
            form={"name": name, "company_title": company_title, "role_tag": role_tag,
                  "bio": bio, **links},
        ), 400

    conn = db.get_conn()
    _, token = db.insert_mentor(conn, name, company_title, role_tag, bio, filename, links, "self-submit")
    conn.close()
    return redirect(url_for("join_thanks", token=token))


@app.route("/join/thanks")
def join_thanks():
    token = request.args.get("token") or ""
    edit_url = url_for("join_edit", token=token, _external=True) if token else None
    return render_template("join_thanks.html", edit_url=edit_url)


@app.route("/join/edit/<token>", methods=["GET"])
def join_edit(token):
    conn = db.get_conn()
    mentor = db.get_mentor_by_token(conn, token)
    conn.close()
    if not mentor:
        abort(404)
    saved = request.args.get("saved") == "1"
    return render_template("join_edit.html", mentor=mentor, error=None, form=None, token=token, saved=saved)


@app.route("/join/edit/<token>", methods=["POST"])
def join_edit_submit(token):
    conn = db.get_conn()
    mentor = db.get_mentor_by_token(conn, token)
    if not mentor:
        conn.close()
        abort(404)

    name = (request.form.get("name") or "").strip()
    company_title = (request.form.get("company_title") or "").strip()
    role_tag = (request.form.get("role_tag") or "").strip()
    bio = (request.form.get("bio") or "").strip()
    links = _extract_links(request.form)
    photo = request.files.get("photo")

    error = None
    if not name or not company_title or not bio:
        error = "姓名、公司/職稱、簡介都要填"

    filename = None
    if not error and photo and photo.filename:
        filename = _process_and_save_photo(photo)
        if not filename:
            error = "這張照片打不開，麻煩改存成 jpg 或 png 格式再上傳一次"

    if error:
        conn.close()
        return render_template(
            "join_edit.html", mentor=mentor, error=error, token=token,
            form={"name": name, "company_title": company_title, "role_tag": role_tag,
                  "bio": bio, **links},
        ), 400

    db.update_mentor(conn, mentor["id"], name, company_title, role_tag, bio, links, filename)
    conn.close()
    return redirect(url_for("join_edit", token=token, saved=1))


@app.route("/join/edit/<token>/delete", methods=["POST"])
def join_edit_delete(token):
    conn = db.get_conn()
    mentor = db.get_mentor_by_token(conn, token)
    if not mentor:
        conn.close()
        abort(404)
    db.delete_mentor(conn, mentor["id"])
    conn.close()
    return redirect(url_for("index"))


def _logged_in() -> bool:
    return bool(session.get("logged_in"))


@app.route("/admin/login", methods=["GET", "POST"])
def admin_login():
    if request.method == "GET":
        return render_template("login.html", error=None)

    username = (request.form.get("username") or "").strip()
    password = request.form.get("password") or ""
    if (
        ADMIN_USER and ADMIN_PASSWORD_HASH
        and username == ADMIN_USER
        and check_password_hash(ADMIN_PASSWORD_HASH, password)
    ):
        session["logged_in"] = True
        session.permanent = True
        return redirect(request.args.get("next") or url_for("admin_list"))
    return render_template("login.html", error="帳號或密碼不對，請再試一次"), 401


@app.route("/admin/logout")
def admin_logout():
    session.clear()
    return redirect(url_for("admin_login"))


@app.route("/admin")
def admin_list():
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
    conn = db.get_conn()
    mentors = db.list_mentors(conn)
    conn.close()
    return render_template("admin_list.html", mentors=mentors)


@app.route("/admin/mentors/new", methods=["GET", "POST"])
def admin_mentor_new():
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))

    if request.method == "GET":
        return render_template("admin_form.html", mentor=None, error=None, form={})

    name = (request.form.get("name") or "").strip()
    company_title = (request.form.get("company_title") or "").strip()
    role_tag = (request.form.get("role_tag") or "").strip()
    bio = (request.form.get("bio") or "").strip()
    links = _extract_links(request.form)
    photo = request.files.get("photo")

    error = None
    if not name or not company_title or not bio:
        error = "姓名、公司/職稱、簡介都要填"
    filename = None
    if not error and photo and photo.filename:
        filename = _process_and_save_photo(photo)
        if not filename:
            error = "這張照片打不開，麻煩改存成 jpg 或 png 格式再上傳一次"
    elif not error:
        error = "請上傳一張照片"

    if error:
        return render_template(
            "admin_form.html", mentor=None, error=error,
            form={"name": name, "company_title": company_title, "role_tag": role_tag,
                  "bio": bio, **links},
        ), 400

    conn = db.get_conn()
    db.insert_mentor(conn, name, company_title, role_tag, bio, filename, links, "seed")
    conn.close()
    return redirect(url_for("admin_list"))


@app.route("/admin/mentors/<int:mentor_id>/edit", methods=["GET", "POST"])
def admin_mentor_edit(mentor_id):
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))

    conn = db.get_conn()
    mentor = db.get_mentor(conn, mentor_id)
    if not mentor:
        conn.close()
        abort(404)

    if request.method == "GET":
        conn.close()
        return render_template("admin_form.html", mentor=mentor, error=None, form=None)

    name = (request.form.get("name") or "").strip()
    company_title = (request.form.get("company_title") or "").strip()
    role_tag = (request.form.get("role_tag") or "").strip()
    bio = (request.form.get("bio") or "").strip()
    links = _extract_links(request.form)
    photo = request.files.get("photo")

    error = None
    if not name or not company_title or not bio:
        error = "姓名、公司/職稱、簡介都要填"

    filename = None
    if not error and photo and photo.filename:
        filename = _process_and_save_photo(photo)
        if not filename:
            error = "這張照片打不開，麻煩改存成 jpg 或 png 格式再上傳一次"

    if error:
        conn.close()
        return render_template(
            "admin_form.html", mentor=mentor, error=error,
            form={"name": name, "company_title": company_title, "role_tag": role_tag,
                  "bio": bio, **links},
        ), 400

    db.update_mentor(conn, mentor_id, name, company_title, role_tag, bio, links, filename)
    conn.close()
    return redirect(url_for("admin_list"))


@app.route("/admin/mentors/<int:mentor_id>/delete", methods=["POST"])
def admin_mentor_delete(mentor_id):
    if not _logged_in():
        return redirect(url_for("admin_login", next=request.path))
    conn = db.get_conn()
    db.delete_mentor(conn, mentor_id)
    conn.close()
    return redirect(url_for("admin_list"))


if __name__ == "__main__":
    db.init_db()
    port = int(os.environ.get("MENTOR100_PORT", 5062))
    app.run(host="0.0.0.0", port=port)

